import { jsPDF } from "jspdf";

async function logoData() {
  const image = new Image();
  image.src = new URL("./logo.webp", import.meta.url).href;
  await image.decode();
  const canvas = document.createElement("canvas");
  canvas.width = image.naturalWidth; canvas.height = image.naturalHeight;
  const context = canvas.getContext("2d");
  context.fillStyle = "white"; context.fillRect(0, 0, canvas.width, canvas.height); context.drawImage(image, 0, 0);
  return { data: canvas.toDataURL("image/png"), ratio: canvas.width / canvas.height };
}
export async function createReceiptPdf(patient, doctor, timestamp, number, logo = null) {
  logo ??= await logoData();
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  doc.addImage(logo.data, "PNG", 16, 14, 50, 50 / logo.ratio);
  doc.setFont("helvetica", "bold"); doc.setFontSize(12); doc.setTextColor(31, 86, 128); doc.text(doctor.clinic, 80, 22);
  doc.setFont("helvetica", "normal"); doc.setFontSize(9); doc.setTextColor(74, 90, 106);
  doc.text(doc.splitTextToSize(doctor.address, 113), 80, 29); doc.text(doctor.email, 80, 41);
  doc.setDrawColor(111, 178, 81); doc.line(16, 51, 194, 51);
  doc.setFontSize(20); doc.setTextColor(31, 86, 128); doc.text("Call Receipt", 16, 64);
  doc.setFontSize(9); doc.text(number, 194, 63, { align: "right" });
  const fields = [["Doctor", doctor.name], ["Specialty", doctor.specialty], ["Provider registration", doctor.registration], ["Patient", patient.name], ["Phone", patient.phone], ["Call date", timestamp.date], ["Call time", timestamp.time], ["Description", patient.reason], ["Outcome", "Call completed and logged"], ["Scheduled date", patient.scheduled_date || "--"], ["Notes", patient.notes || "--"]];
  let y = 78;
  fields.splice(5, 0, ...[
    ["Date of birth", patient.date_of_birth], ["Facility", patient.facility],
    ["Appointment time", patient.appointment_time], ["Customer person", patient.contact_person_name],
  ].filter(([, value]) => value));
  function nextPage() { doc.addPage(); y = 24; }
  for (const [label, value] of fields) {
    if (y > 240) nextPage();
    doc.setFontSize(9); doc.setTextColor(74, 90, 106); doc.text(label, 16, y);
    doc.setTextColor(35, 45, 53); doc.setFontSize(10);
    const lines = doc.splitTextToSize(String(value), 125);
    for (const line of lines) {
      if (y > 245) nextPage();
      doc.text(line, 65, y); y += 5;
    }
    y += 5;
  }
  if (y > 225) nextPage();
  doc.setDrawColor(220, 229, 233); doc.line(16, y, 194, y); y += 10;
  doc.setFont("helvetica", "bold"); doc.setTextColor(31, 86, 128); doc.text("Summary", 16, y);
  doc.setFont("helvetica", "normal"); doc.setTextColor(35, 45, 53); y += 7;
  for (const line of doc.splitTextToSize(`This receipt records a completed call between ${doctor.name} and ${patient.name} on ${timestamp.date} at ${timestamp.time}. Purpose: ${patient.reason}.`, 178)) {
    if (y > 245) nextPage();
    doc.text(line, 16, y); y += 5;
  }
  doc.setFontSize(9); doc.setTextColor(74, 90, 106);
  doc.text("Demonstration provider details and notes. This is a call record, not a bill.", 16, 263);
  doc.text("Digitally generated by Body & Soul Health Center", 16, 275);
  return doc.output("blob");
}
